1→<#
.SYNOPSIS
  External loop: process N Supply Code cases, each in a fresh Grok headless session.

.DESCRIPTION
  Each iteration:
    1. python tools/prepare_next_scj.py  (pick PDF, skip dups, extract text)
    2. grok -p                          (author lean JSON only -- quality-critical)
    3. python tools/finalize_scj.py     (PDF, state, index, git) if the agent did not
10→  Fresh grok process each time (no -c / -r), except stencil tickets: proved
  families (Clause 6.5 billing relegation; Clause 6.8 assessment-hearing;
  contempt of a 6.5 writ dismissed)
  are filled by tools/scj_stencil.py with no grok call. If stencil write
  fails, prepare --demote rewrites the ticket to short/full and grok runs
  once — do not re-prepare the same PDF as stencil. Chrome/git/index
  still run via finalize_scj.py.

.PARAMETER Count
  Max cases to process (default 10).
20→
.PARAMETER RepoRoot
  Repo path (default: parent of tools/).

.PARAMETER MaxTurns
  Max agent turns per case (default 50 -- JSON-only runs need far fewer than 100).

.PARAMETER NoPush
  Finalize commits locally but does not git push (faster; push yourself at the end).

30→.PARAMETER DryRun
  Print commands only; do not extract or invoke grok.

.EXAMPLE
  cd C:\Users\HP\Downloads\Grok\Claude
  powershell -ExecutionPolicy Bypass -File tools\run_next_case_loop.ps1 -Count 100
#>
[CmdletBinding()]
param(
  [int]$Count = 10,
40→  [string]$RepoRoot = "",
  [int]$MaxTurns = 50,
  [switch]$NoPush,
  [switch]$DryRun
)

$ErrorActionPreference = "Stop"
# Native stderr (Python tracebacks, Chrome) must not become terminating
# ErrorRecords. Windows PowerShell wraps 2>&1 lines as errors; with Stop
# the first "Traceback..." line kills the loop and hides the rest.
50→$PSNativeCommandUseErrorActionPreference = $false

if (-not $RepoRoot) {
  $RepoRoot = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)
}
$RepoRoot = (Resolve-Path $RepoRoot).Path
Set-Location $RepoRoot

$ScRoot = Join-Path $RepoRoot "supply-code"
if (-not (Test-Path $ScRoot)) {
60→  throw "Missing supply-code/ under $RepoRoot"
}

$promptFile = Join-Path $RepoRoot "tools\prompts\next_case_once.txt"
$promptShort = Join-Path $RepoRoot "tools\prompts\next_case_short.txt"
$preparePy = Join-Path $RepoRoot "tools\prepare_next_scj.py"
$finalizePy = Join-Path $RepoRoot "tools\finalize_scj.py"
$ticketPath = Join-Path $ScRoot "tmp\NEXT_TICKET.json"
if (-not (Test-Path $promptFile)) { throw "Missing prompt file: $promptFile" }
if (-not (Test-Path $promptShort)) { throw "Missing prompt file: $promptShort" }
70→$maxTurnsUserSet = $PSBoundParameters.ContainsKey("MaxTurns")

$grok = Get-Command grok -ErrorAction SilentlyContinue
if (-not $grok -and -not $DryRun) {
  $candidate = Join-Path $env:USERPROFILE ".grok\bin\grok.exe"
  if (Test-Path $candidate) { $grokPath = $candidate }
  else { throw "grok not found on PATH. Install Grok CLI or add %USERPROFILE%\.grok\bin to PATH." }
} else {
  $grokPath = if ($grok) { $grok.Source } else { "grok" }
}
80→
$logDir = Join-Path $ScRoot "tmp\loop_logs"
New-Item -ItemType Directory -Force -Path $logDir | Out-Null
$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$logFile = Join-Path $logDir "next_case_loop_$stamp.log"
$py = if (Get-Command python -ErrorAction SilentlyContinue) { "python" } else { "python3" }
# UTF-8 mode so child Python open() is not cp1252 on this Windows box.
$env:PYTHONUTF8 = "1"

function Write-Log([string]$msg) {
90→  $line = "[{0}] {1}" -f (Get-Date -Format "HH:mm:ss"), $msg
  Write-Host $line
  Add-Content -Path $logFile -Value $line -Encoding UTF8
}

function Get-NextSeq {
  $s = Get-Content (Join-Path $ScRoot "state\index.json") -Raw -Encoding UTF8 | ConvertFrom-Json
  return [int]$s.next_seq
}

100→function Get-Ticket {
  if (-not (Test-Path $ticketPath)) { return $null }
  return (Get-Content $ticketPath -Raw -Encoding UTF8 | ConvertFrom-Json)
}

function Invoke-LoggedNative {
  param(
    [Parameter(Mandatory = $true)][string]$File,
    [Parameter(Mandatory = $true)][string[]]$Arguments,
    [string]$LogPath = "",
110→    [switch]$Append
  )
  $prev = $ErrorActionPreference
  $ErrorActionPreference = "Continue"
  $code = 1
  try {
    # Stringify ErrorRecords so a Python traceback is logged in full instead
    # of the pipeline dying on the first "Traceback..." line.
    if ($LogPath) {
      if ($Append) {
120→        & $File @Arguments 2>&1 | ForEach-Object { $_.ToString() } | Tee-Object -FilePath $LogPath -Append | Out-Host
      } else {
        & $File @Arguments 2>&1 | ForEach-Object { $_.ToString() } | Tee-Object -FilePath $LogPath | Out-Host
      }
    } else {
      & $File @Arguments 2>&1 | ForEach-Object { Write-Log ($_.ToString()) }
    }
    $code = $LASTEXITCODE
    if ($null -eq $code) { $code = 0 }
  } catch {
130→    Write-Log "ERROR ${File}: $_"
    $code = 1
  } finally {
    $ErrorActionPreference = $prev
  }
  return $code
}

function Write-ReviewMetric {
  param([hashtable]$Fields)
140→  $script = Join-Path $RepoRoot "tools\log_scj_review.py"
  if (-not (Test-Path $script)) { return }
  $argList = @($script)
  foreach ($k in $Fields.Keys) {
    $v = $Fields[$k]
    if ($null -eq $v -or $v -eq "") { continue }
    $argList += "--$k"
    $argList += [string]$v
  }
  try {
150→    & $py @argList 2>&1 | ForEach-Object { Write-Log $_ }
  } catch {
    Write-Log "review-log skipped: $_"
  }
}

Write-Log "Repo: $RepoRoot"
Write-Log "Grok: $grokPath"
Write-Log "Count: $Count | MaxTurns: $MaxTurns | NoPush: $NoPush | Log: $logFile"
Write-Log "Starting next_seq=$(Get-NextSeq)"
160→Write-Log "Review batch: SCJ-488 to SCJ-537 (50 cases). Metrics: supply-code/tmp/pipeline_review/metrics.jsonl"

$ok = 0
$fail = 0
$skipped = 0
$prepFailStreak = 0
$stencilFailStreak = 0

for ($i = 1; $i -le $Count; $i++) {
  $seqBefore = Get-NextSeq
170→  Write-Log "===== CASE $i / $Count | next_seq=$seqBefore ====="

  if ($DryRun) {
    Write-Log "DRY-RUN: $py tools/prepare_next_scj.py"
    Write-Log "DRY-RUN: if ticket.authoring=stencil -> $py tools/scj_stencil.py --write ; on write fail, prepare --demote then grok"
    Write-Log "DRY-RUN: else grok --prompt-file <full|short>"
    Write-Log "DRY-RUN: $py tools/finalize_scj.py SCJ-NNN --source <file>"
    continue
  }

180→  & $py $preparePy
  $prepExit = $LASTEXITCODE
  if ($prepExit -eq 2) {
    Write-Log "STOP: prepare reported NO_INPUT (next_seq=$seqBefore)"
    $skipped = $Count - $i + 1
    break
  }
  if ($prepExit -ne 0) {
    Write-Log "FAIL case $i prepare exit=$prepExit"
    $fail++
190→    $prepFailStreak++
    if ($prepFailStreak -ge 3) {
      Write-Log "STOP: prepare failed $prepFailStreak times in a row (next_seq=$seqBefore). Fix extract then re-run."
      break
    }
    continue
  }
  $prepFailStreak = 0

  $ticket = Get-Ticket
200→  if (-not $ticket -or $ticket.status -ne "READY") {
    Write-Log "FAIL case ${i}: bad ticket $ticketPath"
    $fail++
    continue
  }
  $authoring = [string]$ticket.authoring
  if (-not $authoring) { $authoring = "full" }
  $caseLog = Join-Path $logDir ("case_{0:D2}_{1}_{2}.log" -f $i, $ticket.case_id, $stamp)
  $jsonPath = Join-Path $ScRoot "summaries\json\$($ticket.case_id).json"
  $stencilPy = Join-Path $RepoRoot "tools\scj_stencil.py"
210→  $sw = [System.Diagnostics.Stopwatch]::StartNew()
  $exit = 0
  $tail = ""
  $safetyFinalize = 0
  $demoted = 0
  $didStencil = 0
  $fam = [string]$ticket.stencil_family

  if ($authoring -eq "stencil") {
    Write-Log "ticket $($ticket.case_id) authoring=stencil family=$fam source=$($ticket.source) pages=$($ticket.page_count) words=$($ticket.word_count) -- no grok"
220→    $exit = Invoke-LoggedNative -File $py -Arguments @($stencilPy, "--write") -LogPath $caseLog
    if ($exit -ne 0 -or -not (Test-Path $jsonPath)) {
      if (Test-Path $caseLog) {
        $tail = (Get-Content $caseLog -Tail 8 -ErrorAction SilentlyContinue) -join ' | '
      }
      Write-Log "DEMOTE $($ticket.case_id) stencil write failed -> short/full (do not retry stencil)"
      Write-Log "  tail: $tail"
      $demoteExit = Invoke-LoggedNative -File $py -Arguments @($preparePy, "--demote")
      $ticket = Get-Ticket
      # Trust the rewritten ticket, not $LASTEXITCODE (pipeline can swallow Python's exit).
230→      $authoringNow = if ($ticket) { [string]$ticket.authoring } else { "" }
      if (-not $ticket -or $authoringNow -eq "" -or $authoringNow -eq "stencil") {
        Write-Log "FAIL case $i demote failed exit=$demoteExit authoring=$authoringNow"
        $fail++
        $stencilFailStreak++
        if ($stencilFailStreak -ge 3) {
          Write-Log "STOP: stencil write+demote failed $stencilFailStreak times in a row on $($ticket.case_id). Fix tools/scj_stencil.py then re-run."
          break
        }
        continue
240→      }
      $authoring = $authoringNow
      $demoted = 1
      $stencilFailStreak = 0
      Write-Log "ticket $($ticket.case_id) demoted authoring=$authoring gate=$($ticket.gate) (demote exit=$demoteExit)"
    } else {
      $stencilFailStreak = 0
      $didStencil = 1
      $finArgs = @($finalizePy, $ticket.case_id, "--source", $ticket.source)
      if ($NoPush) { $finArgs += "--no-push" }
250→      $exit = Invoke-LoggedNative -File $py -Arguments $finArgs -LogPath $caseLog -Append
      if ($exit -ne 0) {
        $sw.Stop()
        Write-Log "FAIL case $i stencil finalize exit=$exit"
        $fail++
        continue
      }
    }
  }

260→  if (-not $didStencil) {
    $casePrompt = if ($authoring -eq "short") { $promptShort } else { $promptFile }
    $caseTurns = $MaxTurns
    if (-not $maxTurnsUserSet -and $ticket.max_turns) {
      $caseTurns = [int]$ticket.max_turns
    }
    $demoteNote = if ($demoted) { " (demoted from stencil)" } else { "" }
    Write-Log "ticket $($ticket.case_id) authoring=$authoring$demoteNote source=$($ticket.source) pages=$($ticket.page_count) words=$($ticket.word_count) turns=$caseTurns"
    $grokArgs = @(
      "--cwd", $RepoRoot,
270→      "--prompt-file", $casePrompt,
      "--permission-mode", "bypassPermissions",
      "--always-approve",
      "--max-turns", "$caseTurns",
      "--output-format", "plain",
      "--no-auto-update"
    )
    $exit = Invoke-LoggedNative -File $grokPath -Arguments $grokArgs -LogPath $caseLog
  }
  $sw.Stop()
280→
  $seqMid = Get-NextSeq
  if (Test-Path $caseLog) {
    $tail = (Get-Content $caseLog -Tail 8 -ErrorAction SilentlyContinue) -join ' | '
  }

  # Safety net: JSON exists but finalize did not bump next_seq.
  if ((Test-Path $jsonPath) -and ($seqMid -le $seqBefore)) {
    $safetyFinalize = 1
    Write-Log "JSON unfinalized; running finalize_scj.py"
290→    $finArgs = @($finalizePy, $ticket.case_id, "--source", $ticket.source)
    if ($NoPush) { $finArgs += "--no-push" }
    $finExit = Invoke-LoggedNative -File $py -Arguments $finArgs
    if ($finExit -ne 0) {
      Write-Log "FAIL case $i finalize exit=$finExit"
      Write-Log "  tail: $tail"
      $fail++
      Write-ReviewMetric @{
        event = "loop"; cid = $ticket.case_id; authoring = $authoring
        family = [string]$ticket.stencil_family; source = [string]$ticket.source
300→        pages = [string]$ticket.page_count; words = [string]$ticket.word_count
        citations = [string]$ticket.citation_count; gate = [string]$ticket.gate
        elapsed = [string][int]$sw.Elapsed.TotalSeconds; ok = "0"
        safety_finalize = "1"
        grok = $(if ($didStencil) { "0" } else { "1" })
        demoted = [string]$demoted
        ik_citations = [string]$ticket.ik_citation_count
        text_citations = [string]$ticket.text_citation_count
        demoted_from = $(if ($demoted) { "stencil" } else { "" })
      }
310→      continue
    }
  }

  $seqAfter = Get-NextSeq
  $elapsed = [int]$sw.Elapsed.TotalSeconds
  $okFlag = 0

  if ($seqAfter -gt $seqBefore) {
    Write-Log "OK case $i $($ticket.case_id) done -> next_seq=$seqAfter elapsed=${elapsed}s"
320→    Write-Log "  tail: $tail"
    $ok++
    $okFlag = 1
  } elseif ($tail -match "NO_INPUT") {
    Write-Log "STOP: agent reported NO_INPUT"
    break
  } elseif ($exit -ne 0 -and $null -ne $exit) {
    Write-Log "FAIL case $i exit=$exit elapsed=${elapsed}s next_seq=$seqAfter"
    Write-Log "  tail: $tail"
    $fail++
330→  } elseif ($tail -match "FAILED") {
    Write-Log "FAIL case $i agent FAILED next_seq still $seqAfter"
    Write-Log "  tail: $tail"
    $fail++
  } else {
    Write-Log "WARN case $i exit=0 but next_seq unchanged ($seqBefore). Check $caseLog"
    Write-Log "  tail: $tail"
    $fail++
  }

340→  Write-ReviewMetric @{
    event = "loop"; cid = $ticket.case_id; authoring = $authoring
    family = [string]$ticket.stencil_family; source = [string]$ticket.source
    pages = [string]$ticket.page_count; words = [string]$ticket.word_count
    citations = [string]$ticket.citation_count; gate = [string]$ticket.gate
    elapsed = [string]$elapsed; ok = [string]$okFlag
    safety_finalize = [string]$safetyFinalize
    grok = $(if ($didStencil) { "0" } else { "1" })
    demoted = [string]$demoted
    ik_citations = [string]$ticket.ik_citation_count
350→    text_citations = [string]$ticket.text_citation_count
    demoted_from = $(if ($demoted) { "stencil" } else { "" })
  }
}

Write-Log "===== DONE ok=$ok fail=$fail skipped_remaining~$skipped next_seq=$(Get-NextSeq) ====="
Write-Log "Full log: $logFile"
try {
  & $py (Join-Path $RepoRoot "tools\log_scj_review.py") --summary 2>&1 | ForEach-Object { Write-Log $_ }
} catch { }
360→Write-Host ""
Write-Host "Summary: ok=$ok fail=$fail | next_seq=$(Get-NextSeq) | log=$logFile"
exit $(if ($fail -gt 0) { 1 } else { 0 })

